define(['jquery', 'Magento_Ui/js/modal/modal'], function($, modal) {
    return function(config) {
        var loginButton = $('#store-login-form').find('button[type=submit]');
        var loginUrl = config.getStoreLoginPostUrl;
        var recapSiteKey = config.recaptchaSitekey;
        var options = {
            type: 'popup',
            responsive: true,
            innerScroll: true,
            modalClass: "popup-center storelogin-popup",
            buttons: []
        };
        var popup = modal(options, $('#login-modal-form'));
        $(".store-login-form").on('click', function() {
            $("#login-modal-form").modal("openModal");
            initializeReCaptcha();
        });
        $("#store-login-form").submit(function(e) {
            e.preventDefault();
            localStorage.removeItem('store_timer');
            localStorage.removeItem('store_name');
            var formData = getFormData($(this));
            $('body').loader().loader('show');
            $.ajax({
                type: "POST",
                url: loginUrl,
                data: formData,
                dataType: 'json',
                success: function(data) {
                    $('body').loader().loader('hide');
                    if (data.errors == false) {
                        const decoded = atob(atob(data.message)).split("").reverse().join("");
                        const finalMsg = atob(decoded);
                        $('.response-msg').html("<div class='success'>" + finalMsg + "</div>");
                        setTimeout(() => {
                            $("#login-modal-form").modal("closeModal");
                            location.reload();
                        }, 2000);
                    } else {
                        const errorDecoded = atob(atob(data.message)).split("").reverse().join("");
                        const errorFinalMsg = atob(errorDecoded);
                        $('.response-msg').html("<div class='error'>" + errorFinalMsg + "</div>");
                    }
                    setTimeout(function() {
                        $('.response-msg').html(null);
                    }, 5000);
                },
                error: function(response) {
                    $('body').loader().loader('hide');
                },
            });
        });

        function getFormData(formElem) {
            var unindexed_array = formElem.serializeArray();
            var indexed_array = {};
            jQuery.map(unindexed_array, function(n, i) {
                indexed_array[n['name']] = n['value'];
            });
            return indexed_array;
        }

        function initializeReCaptcha() {
            $('#login-recaptcha').val('');
            var element_render = '';
            var validate = '';
            element_render = 'tab-login-recaptcha';
            validate = 'login-recaptcha';
            if ($('#' + element_render).children().length === 0 && recapSiteKey != "") {
                grecaptcha.render(element_render, {
                    'sitekey': recapSiteKey,
                    'theme': "light",
                    'type': "image",
                    'size': "normal",
                    'callback': function(response) {
                        if (response.length > 0) {
                            $('#' + validate).val('success');
                        }
                    }
                });
            }
        }
    }
});